def _resolve_relevant_ids(gold: dict, collection: Any) -> set[str]:
    """
    Resolve relevant node IDs from a gold entry.

    Supports two formats:
      - {"relevant_ids": ["file.c::sym", ...]}           # explicit IDs
      - {"expected_symbols": [...], "expected_files": [...]}  # symbol names → lookup
    """
    if "relevant_ids" in gold:
        return set(gold["relevant_ids"])

    symbols: list[str] = gold.get("expected_symbols", [])
    files: list[str] = gold.get("expected_files", [])
    if not symbols and not files:
        return set()

    relevant: set[str] = set()

    # Build candidate IDs as {file}::{symbol} for every (file, symbol) pair,
    # then verify they exist in the collection.
    if symbols and files:
        candidate_ids = [f"{f}::{s}" for f in files for s in symbols]
        try:
            res = collection.get(ids=candidate_ids, include=[])
            relevant.update(res["ids"])
        except Exception:
            pass

    # Also try symbol-only lookup across all files via metadata filter.
    for sym in symbols:
        try:
            res = collection.get(
                where={"symbol_name": {"$eq": sym}},
                include=[],
                limit=20,
            )
            relevant.update(res["ids"])
        except Exception:
            pass

    return relevant


